WITH topic_counts AS (
  SELECT topic, SUM(CASE WHEN content_type='thread' THEN 5 ELSE 1 END)::integer AS score, MAX(created_at) AS latest
  FROM hntrendingtopics__hn_topics GROUP BY topic ORDER BY score DESC, latest DESC LIMIT 50
), recent AS (
  SELECT COALESCE(jsonb_agg(stories),'[]'::jsonb) AS episode_stories FROM (
    SELECT stories FROM podcast_episodes WHERE stories IS NOT NULL AND date < $1::date ORDER BY date DESC LIMIT 45
  ) e
)
SELECT COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM topic_counts t),'[]'::jsonb) AS trending_topics, recent.episode_stories AS recent_episode_stories FROM recent;

