import re
from urllib.parse import urlsplit, parse_qsl, urlencode, urlunsplit

context = _items[0]['json']
def story_keys(story):
    keys = []
    for field in ('url', 'hnUrl', 'hn_url'):
        value = story.get(field)
        if not value: continue
        parts = urlsplit(str(value).strip())
        if not parts.scheme or not parts.netloc: continue
        path = parts.path.rstrip('/') or '/'
        query = ''
        if parts.netloc.lower() == 'news.ycombinator.com' and path == '/item':
            hn_id = dict(parse_qsl(parts.query)).get('id')
            if hn_id: query = urlencode({'id': hn_id})
        keys.append('url:' + urlunsplit((parts.scheme.lower(), parts.netloc.lower(), path, query, '')))
    title = re.sub(r'[^a-z0-9]+', '-', str(story.get('title') or '').lower()).strip('-')
    if title: keys.append('title:' + title)
    return sorted(set(keys))
recent_keys = set()
for episode_stories in context.get('recent_episode_stories') or []:
    if isinstance(episode_stories, str):
        import json
        episode_stories = json.loads(episode_stories)
    if isinstance(episode_stories, list):
        for story in episode_stories:
            if isinstance(story, dict): recent_keys.update(story_keys(story))
context['recentStoryKeys'] = sorted(recent_keys)
return [{'json': context}]
